SELECT customer_id, status, CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END AS end_cohort, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, MIN(end_date) AS first_end_date, ROUND(AVG(monthly_fee), 2) AS avg_monthly_fee FROM subscriptions GROUP BY customer_id, status, CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY customer_id DESC, first_end_date;
